  const ::flatbuffers::Vector<::flatbuffers::Offset<QRPColumn>> *COLUMNS() const {
    return GetPointer<const ::flatbuffers::Vector<::flatbuffers::Offset<QRPColumn>> *>(VT_COLUMNS);
  }
